insert into workouts (owner_id, title, description, mode, sessions_per_week, program_weeks) values (null, 'Kettlebell Month 1 - Foundation', '<p>Single 35lb kettlebell &mdash; Weeks 1-4. Goal: rebuild movement quality and base conditioning.</p><p>Warm up 5 minutes first: arm circles, hip openers, a few bodyweight squats, light swings.</p><p>Progress week to week by adding 2-3 reps to swings/squats, or add 1 set once form is solid.</p>', 'MANUAL', 3, 4);
